// Notes — durable whole-value key/value notes with compare-and-set semantics, per-namespace
// and global capacity caps, idle reclamation, and the three reserved namespaces
// (room-owners/room-allow/room-nonce, plus the ordinary-but-reserved topic namespace) that
// back room ownership for the `rooms` component (see quint-specs/rooms.qnt, which already
// treats owner/allow as an external dependency it only reads the OUTCOME of).
//
// `note_set` is the bare store-level primitive (store.py:1266): it has NO namespace
// awareness at all — by the store's own docstring it provides "no ownership fencing". Every
// namespace rule (room-owners first-claim, room-allow ownership, room-nonce being
// server-only) is enforced ONLY by app.py's `_note_write_gate`, which the three HTTP
// actions call and `note_set` does not. Modeling `note_set` as its own directly-reachable
// action (per the component map) is therefore not a hypothetical: it is exactly how a future
// internal caller that forgets the gate would behave, and `reserved_ns_only_via_gate` below
// is the property that catches it.
//
// Idle reclamation (`_reap`, store.py:751) is folded in as its own environment action
// (`env_note_reaped`) rather than embedded inside every write action: `_reap` is
// throttle-gated (REAP_EVERY) and wall-clock-driven, so — per quint-modeling's
// abstract-time guidance ("a timeout is just the round advancing") — eligibility to reap is
// modeled as an independent nondet event rather than real mtimes. Guard notes
// (room-owners/room-allow/room-nonce) are protected while `roomActivity` is true for their
// room, mirroring `_guards_a_live_room` (store.py:735) — but `roomActivity` is monotonic
// here (never reset), a deliberately MORE PROTECTIVE simplification: a real guard note can
// eventually be reaped once its room itself goes idle, which this model never represents
// (rooms.qnt does not model room idling/deletion either, so this stays consistent with its
// sibling spec).
module notes_store {
  import basicSpells.* from "./spells/basicSpells"

  // --------------------------------------------------------------------- domains

  pure val OWNERS_NS = "room-owners"   // /kv/room-owners/<room> -> the owner's did:key
  pure val ALLOW_NS = "room-allow"     // /kv/room-allow/<room>  -> space-separated did:keys
  pure val NONCE_NS = "room-nonce"     // /kv/room-nonce/<room>  -> highest nonce accepted
  pure val TOPIC_NS = "topic"          // /kv/topic/<room>       -> ordinary, world-writable
  pure val NS_SET: Set[str] = Set(OWNERS_NS, ALLOW_NS, NONCE_NS, TOPIC_NS)

  // Kept at the sizes proven reachable by the generate-stage battery: a wider domain (real
  // "d-*" room ids beyond bounty/busy, per-value plainN slots) OOM-crashed the Rust
  // evaluator during wiring (686K+ pick combinations per `any{}` visit in the signed
  // actions). The oracle client still maps EVERY real room id the wired tests use onto
  // "d-bounty"/"d-busy" (ownable) or "lobby" (not) via a per-test categorize() slot — see
  // app.py's _note_key_oracle_category — so replay fidelity for room identity is
  // preserved; what's given up is per-test distinctness for a generic (non-reserved-ns)
  // note beyond "note1", and for a "plain" value beyond one bucket. Collisions there are a
  // refine-loop concern (a specific replay mismatch on a specific test), not a reason to
  // widen this domain again.
  pure val KEYS: Set[str] = Set("d-bounty", "d-busy", "lobby", "note1")
  pure val OWNABLE_KEYS: Set[str] = Set("d-bounty", "d-busy")

  pure val DIDS: Set[str] = Set("did:key:alice", "did:key:bob", "did:key:mallory")
  pure val NONCE_TOKENS: Set[str] = Set("n0", "n1", "n2", "n3")
  pure val VALUES_ALL: Set[str] = DIDS.union(Set("list_ok", "list_bad", "plain")).union(NONCE_TOKENS)
  // `expectVal` is a plain str (not Option[str]) with an explicit "no condition" sentinel —
  // the oracle rejects a logged JSON scalar against an Option-typed pick domain (it never
  // matches, present or absent), and unlike `signer` this argument never discriminates
  // WHICH action fires, so the sibling-action split used elsewhere doesn't apply either.
  pure val NO_CONDITION = "no_condition"
  pure val EXPECT_DOMAIN: Set[str] = VALUES_ALL.union(Set(NO_CONDITION))
  pure val BOOLS: Set[bool] = Set(true, false)

  pure def isDid(v: str): bool = DIDS.contains(v)
  pure def isValidAllowList(v: str): bool = DIDS.contains(v) or v == "list_ok"
  pure def isNonceToken(v: str): bool = NONCE_TOKENS.contains(v)
  pure def nonceValue(v: str): int =
    if (v == "n0") 0 else if (v == "n1") 1 else if (v == "n2") 2 else if (v == "n3") 3 else -1
  pure def isGuardNs(ns: str): bool = ns == OWNERS_NS or ns == ALLOW_NS or ns == NONCE_NS

  // Scaled down (real MAX_NOTES_PER_NS=MAX_ROOMS=5120, MAX_NOTES_TOTAL=8x that): the ratio
  // that matters is "global caps before every namespace maxes out individually"
  // (4 namespaces x MAX_PER_NS_MODEL=2 = 8 > MAX_TOTAL_MODEL=4), not the magnitude. Kept at
  // the values proven reachable by the generate-stage battery — headroom for the
  // generic-namespace collapse comes from more gkeyN slots, never from raising these.
  pure val MAX_PER_NS_MODEL = 2
  pure val MAX_TOTAL_MODEL = 4

  pure val ALL_NOTE_IDS: Set[(str, str)] = tuples(NS_SET, KEYS)

  // --------------------------------------------------------------------- state

  type State = {
    notes: (str, str) -> Option[str],
    roomActivity: str -> bool,          // mirrors last_seq(room) > 0 (a rooms.qnt fact)
    reservedNsUnguardedWrite: bool,      // ghost: did note_set ever touch a reserved ns raw?
    everReaped: bool,                    // ghost: did env_note_reaped ever fire?
    stepped: bool,                       // diagnostic latch: did ANY action ever fire?
  }

  var state: State

  action init = all {
    state' = {
      notes: ALL_NOTE_IDS.mapBy(_ => None),
      roomActivity: KEYS.mapBy(_ => false),
      reservedNsUnguardedWrite: false,
      everReaped: false,
      stepped: false,
    },
  }

  // --------------------------------------------------------------------- pure logic

  pure def nsCount(st: State, ns: str): int =
    ALL_NOTE_IDS.filter(id => id._1 == ns and st.notes.get(id) != None).size()
  pure def totalCount(st: State): int =
    ALL_NOTE_IDS.filter(id => st.notes.get(id) != None).size()

  // note_set's CAS core (store.py:1295-1300): capacity only gates a brand-new note; the two
  // `expectVal`/`expect_absent` conjuncts are independent, exactly like the code's two `if`s.
  pure def canNoteSet(st: State, ns: str, key: str, expectVal: str, expect_absent: bool): bool = {
    val existing = st.notes.get((ns, key))
    and {
      existing != None or (nsCount(st, ns) < MAX_PER_NS_MODEL and totalCount(st) < MAX_TOTAL_MODEL),
      not(expect_absent) or existing == None,
      expectVal == NO_CONDITION or existing == Some(expectVal),
    }
  }
  pure def applyNoteSet(st: State, ns: str, key: str, value: str): State =
    { ...st, notes: st.notes.set((ns, key), Some(value)), stepped: true }

// _burn_nonce's core (app.py:1426-1451): current.isdigit() failing (garbage left by an
// unguarded note_set) permanently locks the nonce out, matching `isNonceToken(c)` being
// false forever after. Capacity is checked too — a first-ever burn for a room creates a
// new room-nonce note, subject to the same caps as any other note.
pure def canBurn(st: State, room: str, nonceTok: str): bool = {
  val current = st.notes.get((NONCE_NS, room))
  and {
    match current {
      | Some(c) => isNonceToken(c) and nonceValue(nonceTok) > nonceValue(c)
      | None => true
    },
    current != None or (nsCount(st, NONCE_NS) < MAX_PER_NS_MODEL and totalCount(st) < MAX_TOTAL_MODEL),
  }
}
pure def applyBurn(st: State, room: str, nonceTok: str): State =
  { ...st, notes: st.notes.set((NONCE_NS, room), Some(nonceTok)), stepped: true }

// _note_write_gate (app.py:1312-1402), flattened to independent conjuncts exactly matching
// the code's separate `if`s rather than a nested match, so each one is its own falsifiable
// guard-scenario conjunct (audit #4).
pure def gateOk(st: State, ns: str, key: str, value: str, signerOpt: Option[str]): bool =
  if (ns == NONCE_NS) false                                    // server-only, always denied
  else if (ns != OWNERS_NS and ns != ALLOW_NS) (signerOpt == None)  // world-writable, unsigned only
  else if (ns == OWNERS_NS) {
    val current = st.notes.get((OWNERS_NS, key))
    and {
      OWNABLE_KEYS.contains(key),
      isDid(value),
      current == None or signerOpt == Some(unwrap(current)),        // hand-over: signer==owner
      current != None or signerOpt == Some(value),                  // first claim: signer==value
      current != None or not(st.roomActivity.get(key)),             // first claim: room inactive
    }
  } else {
    val owner = st.notes.get((OWNERS_NS, key))
    and {
      owner != None,
      owner == None or signerOpt == Some(unwrap(owner)),
      isValidAllowList(value),
    }
  }

// --------------------------------------------------------------------- actions

// note_set(root, ns, key, value, expectVal=None, expect_absent=False) — mutates, CAS
// (store.py:1266). The raw primitive: no namespace gate at all, hence the ghost flag.
action note_set(ns: str, key: str, value: str, expectVal: str, expect_absent: bool): bool = all {
  canNoteSet(state, ns, key, expectVal, expect_absent),
  state' = { ...applyNoteSet(state, ns, key, value),
             reservedNsUnguardedWrite: state.reservedNsUnguardedWrite or isGuardNs(ns) },
}

// GET /kv/{ns}/{key}/set/{value} -> note_write — mutates, unsigned CAS (app.py:1405).
action GET_kvnskeysetvalue___note_write(ns: str, key: str, value: str, expectVal: str, expect_absent: bool): bool = all {
  gateOk(state, ns, key, value, None),
  canNoteSet(state, ns, key, expectVal, expect_absent),
  state' = applyNoteSet(state, ns, key, value),
}

// GET /kv/{ns}/{key}/set-signed/{did}/{sig}/{nonce}/{value} -> note_write_signed —
// mutates, signed (app.py:1454). `_burn_nonce` commits FIRST and is not rolled back if the
// guarded note_set that follows then fails (a documented, non-refundable behavior, and a
// component-map adversary row) — so the guard for this action is only gate+burn; the
// second write's own success is folded into the update, not the guard, exactly mirroring
// that the burn's disk write already happened before note_set could raise.
action GET_kvnskeyset_signeddidsignoncevalue___note_write_signed(
  ns: str, key: str, value: str, did: str, nonceTok: str, expectVal: str, expect_absent: bool
): bool = {
  val afterBurn = applyBurn(state, key, nonceTok)
  val secondOk = canNoteSet(afterBurn, ns, key, expectVal, expect_absent)
  all {
    gateOk(state, ns, key, value, Some(did)),
    canBurn(state, key, nonceTok),
    state' = if (secondOk) applyNoteSet(afterBurn, ns, key, value) else afterBurn,
  }
}

// POST /kv/{ns}/{key} -> note_post — mutates, JSON body, optional signature (app.py:1482).
// Split into unsigned/signed sibling actions, mirroring rooms.qnt's room_post_unsigned /
// room_post_signed split: the oracle replay engine cannot pin a logged JSON `null` to
// `None` for an Option-typed argument, so both route from the SAME logged event via
// actionNameMap at the wire stage rather than sharing one Option[str]-signer action here.
action note_post_unsigned(ns: str, key: str, value: str, expectVal: str, expect_absent: bool): bool = all {
  gateOk(state, ns, key, value, None),
  canNoteSet(state, ns, key, expectVal, expect_absent),
  state' = applyNoteSet(state, ns, key, value),
}

action note_post_signed(
  ns: str, key: str, value: str, did: str, nonceTok: str, expectVal: str, expect_absent: bool
): bool = {
  val afterBurn = applyBurn(state, key, nonceTok)
  val secondOk = canNoteSet(afterBurn, ns, key, expectVal, expect_absent)
  all {
    gateOk(state, ns, key, value, Some(did)),
    canBurn(state, key, nonceTok),
    state' = if (secondOk) applyNoteSet(afterBurn, ns, key, value) else afterBurn,
  }
}

// _burn_nonce(room, nonce) — mutates, CAS-writes the spent nonce, single-use (app.py:1426).
// Reachable on its own (not only nested inside the two signed lanes above) per the scaffold.
action _burn_nonce(room: str, nonceTok: str): bool = all {
  canBurn(state, room, nonceTok),
  state' = applyBurn(state, room, nonceTok),
}

// Environment: a room receives a message from the (separate) rooms component, making
// `_note_write_gate`'s "already has messages" first-claim check active for it
// (app.py:1374-1380) — modeled here, not in rooms.qnt, because it is THIS gate that reads
// it. No logAction site of its own; sim-side machinery only, like a crash/timeout action.
action env_room_gets_message(room: str): bool = all {
  state' = { ...state, roomActivity: state.roomActivity.set(room, true), stepped: true },
}

// Environment: idle reclamation (_reap, store.py:751). A guard note stays protected only
// while its room is currently active; every other note (guard notes for an inactive room,
// or any ordinary note) is eligible at any time — the abstraction for "idle >= 7 days".
action env_note_reaped(ns: str, key: str): bool = {
  val protectedByLiveRoom = isGuardNs(ns) and state.roomActivity.get(key)
  all {
    state.notes.get((ns, key)) != None,
    not(protectedByLiveRoom),
    state' = { ...state, notes: state.notes.set((ns, key), None), everReaped: true, stepped: true },
  }
}

// --------------------------------------------------------------------- step

action step = any {
  { nondet ns = NS_SET.oneOf()
    nondet key = KEYS.oneOf()
    nondet value = VALUES_ALL.oneOf()
    nondet expectVal = EXPECT_DOMAIN.oneOf()
    nondet expect_absent = BOOLS.oneOf()
    note_set(ns, key, value, expectVal, expect_absent) },

  { nondet ns = NS_SET.oneOf()
    nondet key = KEYS.oneOf()
    nondet value = VALUES_ALL.oneOf()
    nondet expectVal = EXPECT_DOMAIN.oneOf()
    nondet expect_absent = BOOLS.oneOf()
    GET_kvnskeysetvalue___note_write(ns, key, value, expectVal, expect_absent) },

  { nondet ns = NS_SET.oneOf()
    nondet key = KEYS.oneOf()
    nondet value = VALUES_ALL.oneOf()
    nondet did = DIDS.oneOf()
    nondet nonceTok = NONCE_TOKENS.oneOf()
    nondet expectVal = EXPECT_DOMAIN.oneOf()
    nondet expect_absent = BOOLS.oneOf()
    GET_kvnskeyset_signeddidsignoncevalue___note_write_signed(ns, key, value, did, nonceTok, expectVal, expect_absent) },

  { nondet ns = NS_SET.oneOf()
    nondet key = KEYS.oneOf()
    nondet value = VALUES_ALL.oneOf()
    nondet expectVal = EXPECT_DOMAIN.oneOf()
    nondet expect_absent = BOOLS.oneOf()
    note_post_unsigned(ns, key, value, expectVal, expect_absent) },

  { nondet ns = NS_SET.oneOf()
    nondet key = KEYS.oneOf()
    nondet value = VALUES_ALL.oneOf()
    nondet did = DIDS.oneOf()
    nondet nonceTok = NONCE_TOKENS.oneOf()
    nondet expectVal = EXPECT_DOMAIN.oneOf()
    nondet expect_absent = BOOLS.oneOf()
    note_post_signed(ns, key, value, did, nonceTok, expectVal, expect_absent) },

  { nondet room = KEYS.oneOf()
    nondet nonceTok = NONCE_TOKENS.oneOf()
    _burn_nonce(room, nonceTok) },

  { nondet room = KEYS.oneOf()
    env_room_gets_message(room) },

  { nondet ns = NS_SET.oneOf()
    nondet key = KEYS.oneOf()
    env_note_reaped(ns, key) },
}

// --------------------------------------------------------------------- properties

/// The per-namespace and global note caps hold exactly, even as creates land across every
/// namespace at once — if either overshoots, the operator's disk fills past the documented
/// budget (note_set's caps must be evaluated inside note_set's own bookkeeping, not derived
/// from a separate count that a race could let drift, tests/test_app.py:598-628).
val notes_caps_hold: bool =
  NS_SET.forall(ns => nsCount(state, ns) <= MAX_PER_NS_MODEL) and totalCount(state) <= MAX_TOTAL_MODEL

/// A reserved namespace (room-owners, room-allow, room-nonce) is only ever written through
/// `_note_write_gate` — never via the bare `note_set` primitive, which has no ownership
/// fencing at all. If this is violated, an attacker (or a future unguarded caller) can
/// silently seize a room's ownership or allow-list, or permanently jam its nonce counter,
/// without ever proving key possession — locking out the legitimate owner.
val reserved_ns_only_via_gate: bool =
  not(state.reservedNsUnguardedWrite)

/// Only a `d-` room outside UNOWNABLE_ROOMS can ever hold a room-owners entry. If violated,
/// an attacker who reaches note_set can claim the un-ownable "lobby" room — exactly the

    the separate flag rather than a sentinel.
    """
    if source.get("if_absent") not in (None, "", False, "0", "false"):
        return None, True
    expect = source.get("if")
    return (str(expect) if expect is not None else None), False


def _note_write_gate(ns: str, key: str, value: str, signer: str | None) -> Response | None:
    """Two reserved namespaces carry room ownership, and only those two take signed writes.

    Not a general signed-kv system: a note is world-writable by design and stays that way,
    because "notes anyone can read but only one key can write" is a different product. The
    exception exists because a room owner has to be able to publish an allow-list that a
    stranger cannot rewrite — without that, ownership is a note anyone can overwrite, which
    is not ownership.
    """
    if ns == store.NONCE_NS:
        return text(
            f"403 /kv/{store.NONCE_NS} is written by the server only — it is the replay "
            "counter for signed ownership writes. Read it freely.",
            403,
        )
    if ns not in (store.OWNERS_NS, store.ALLOW_NS):
        if signer is not None:
            return text(
                f"400 signed note writes are only accepted for {store.OWNERS_NS} and "
                f"{store.ALLOW_NS}. Every other namespace is world-writable — use "
                f"/kv/{ns}/{key}/set/<value>.",
                400,
            )
        return None
    if ns == store.OWNERS_NS:
        if not store.ownable(key):
            return text(
                f"403 /r/{key} cannot be owned. Only d- rooms are ownable, and never "
                f"{' or '.join(store.UNOWNABLE_ROOMS)}: claiming a room that already has "
                "people in it would lock them out of somewhere they were already talking.",
                403,
            )
        if not didkey.is_did(value):
            return text(
                "400 a room owner is a did:key, not a nickname — a name nobody can prove "
                "they hold cannot own anything. Claim with the key you sign with.",
                400,
            )
        current = store.note_get(ROOT, store.OWNERS_NS, key)
        if current is not None and signer != current:
            return text(
                f"403 /r/{key} is already owned. Only the current owner can hand it over, "
                f"with a signed write: /kv/{store.OWNERS_NS}/{key}/set-signed/...",
                403,
            )
        # A *first* claim must be signed by the key it stores. Checking that `value` parses
        # as a did:key only proves it is well-formed, so an unsigned claim let a stranger
        # lock a room to any key at all — including someone else's, handing them a room
        # they never asked for and locking everyone else out until the note idled away.
        #
        # Hand-over is the other case and is deliberately not held to this: there the
        # signer is the current owner and `value` is the recipient, who cannot sign for a
        # room they do not yet hold. The check above already proved the signer is the owner.
        if current is None and signer != value:
            return text(
                f"403 claiming /r/{key} takes a signed write proving you hold that key: "
                f"/kv/{store.OWNERS_NS}/{key}/set-signed/<did:key>/<sig>/<nonce>/<the same did:key>. "
                "Anyone can type a did:key; only its holder can sign with it.",
                403,
            )
        # "Claiming a room people are already talking in would lock them out" was documented
        # for the un-ownable rooms and never enforced for d- ones. Ownership is from birth.
        if current is None and store.last_seq(ROOT, key) > 0:
            return text(
                f"403 /r/{key} already has messages, so it can no longer be claimed — "
                "a room is ownable from birth or not at all, or claiming becomes a way to "
                "take over a conversation already in progress.",
                403,
            )
        return None
    owner = store.note_get(ROOT, store.OWNERS_NS, key)
    if owner is None:
        return text(
            f"403 /r/{key} has no owner, so it has no allow-list. Claim it first: "
            f"/kv/{store.OWNERS_NS}/{key}/set/<your did:key>?if_absent=1",
            403,
        )
    if signer != owner:
        return text(
            f"403 only the owner of /r/{key} may write its allow-list, with a signed "
            f"write: /kv/{store.ALLOW_NS}/{key}/set-signed/<did:key>/<sig>/<nonce>/<keys>",
            403,
        )
    bad = [token for token in value.split() if not didkey.is_did(token)]
    if bad or not value.split():
        return text(
            f"400 an allow-list is space-separated did:keys; {bad[0] if bad else value!r} "
            "is not one. Fail closed: a list with an unparseable entry lets nobody in.",
            400,
        )
    return None


_NOTES_NO_CONDITION = "no_condition"


def _note_cas_oracle_args(expect: str | None, expect_absent: bool) -> list[dict]:
    """`expectVal` is a plain str in the spec (not Option[str]) with an explicit
    "no_condition" sentinel: the oracle rejected BOTH a logged JSON `null` (unsupported
    value shape) and a bare scalar matched against an Option-typed pick domain (never
    matched, present or absent) — plain-str-plus-sentinel is the shape every other
    argument here already uses successfully."""
    return [
        {"name": "expect_absent", "value": expect_absent},
        {
            "name": "expectVal",
            "value": _note_value_oracle_category(expect) if expect is not None else _NOTES_NO_CONDITION,
        },
    ]


def _note_set_with_oracle(
    action: str, ns: str, key: str, value: str, expect: str | None, expect_absent: bool,
    base_args: list[dict],
) -> dict:
    """store.note_set, wrapped so the oracle sees exactly what the CODE decided: a
    completed transition on success, or the same action tagged `outcome: "rejected"` on
    the CAS/capacity guard it enforces (StoreError/StoreConflictError) — the reject-side
    evidence quint-specs/notes-store.qnt's canNoteSet guard scenarios need. Re-raises so
    the existing StoreError/StoreConflictError exception handlers are unaffected — this
    only adds oracle visibility around the call, never changes its outcome."""
    args = [*base_args, *_note_cas_oracle_args(expect, expect_absent)]
    try:
        meta = store.note_set(ROOT, ns, key, value, expect=expect, expect_absent=expect_absent)
    except (StoreConflictError, StoreError):
        _notes_oracle.log_action(action, [*args, {"name": "outcome", "value": "rejected"}])
        raise
    _notes_oracle.log_action(action, args)
    return meta


def note_write(request: Request) -> Response:
    left, retry = take(request, "write", RATE_WRITE)
    if retry:
        return limited("write", RATE_WRITE, retry)
    p = request.path_params
    ns, key = p["ns"], p["key"]
    value = store.clean_text(p["value"], store.MAX_VALUE_CHARS)
    action = "GET_kvnskeysetvalue___note_write"
    base_args = [
        {"name": "ns", "value": _note_ns_oracle_category(ns)},
        {"name": "key", "value": _note_key_oracle_category(ns, key)},
        {"name": "value", "value": _note_value_oracle_category(value)},
    ]
    expect, expect_absent = _condition(dict(request.query_params))
    denied = _note_write_gate(ns, key, value, None)
    if denied:
        _notes_oracle.log_action(
            action,
            [*base_args, *_note_cas_oracle_args(expect, expect_absent), {"name": "outcome", "value": "rejected"}],
        )
        return denied

    assert _say_signed(client, "mb-p-7f3a9c", did, sign, "letter").status_code == 200
    assert "mb-p-7f3a9c" not in client.get("/rooms").text
    assert "mb-p-7f3a9c" not in client.get("/r/events").text  # nor announced
    assert "letter" in client.get("/r/mb-p-7f3a9c").text  # but reachable by name


# ---------------------------------------------------------------------- owned rooms


def _claim(client, room, did, sign, nonce=1):
    """A claim is a signed write storing the signer's own key. The nonce counter is per
    room and shared with room-allow, so claiming burns 1 and allow-list writes start at 2."""
    return _set_signed(client, "room-owners", room, did, sign, did, nonce)


def _set_signed(client, ns, key, did, sign, value, nonce=1):
    return client.get(
        f"/kv/{ns}/{key}/set-signed/{did}/{sign(f'{ns}|{key}|{nonce}|{value}')}/{nonce}/{value}"
    )


def _signed_note_payload(ns, key, did, sign, value, nonce=1, **condition):
    import store

    swept = store.clean_text(value, store.MAX_VALUE_CHARS)
    return {
        "value": value,
        "did": did,
        "sig": sign(f"{ns}|{key}|{nonce}|{swept}"),
        "nonce": str(nonce),
        **condition,
    }


